"""Main entrypoint for the Shopify Reporting MCP Server.
"""

import os
import sys
import json
from contextlib import asynccontextmanager
from typing import AsyncGenerator

from dotenv import load_dotenv
from fastmcp import FastMCP
from fastapi import FastAPI, Request, Response
from fastapi.responses import JSONResponse

# Load environment variables
load_dotenv()

# Initialize logging first
from utils.logging import setup_logging, get_logger, set_request_context, clear_request_context

setup_logging(
    log_level=os.getenv("LOG_LEVEL", "INFO"),
    log_format="plain"
)

logger = get_logger(__name__)

# Import Phase 1 components
from auth import (
    get_oauth_flow,
    get_encryption,
    get_rbac_manager,
    UserRole,
    Permission,
)
from database import init_database, run_migrations
from metrics import get_metric_registry
from utils.errors import handle_exception, format_error_response, ShopifyMCPError


@asynccontextmanager
async def lifespan(app: FastAPI) -> AsyncGenerator[None, None]:
    """Application lifespan manager - startup and shutdown."""
    logger.info("Starting Shopify Reporting MCP Server - Phase 1 Foundation")

    try:
        # Initialize database and run migrations
        logger.info("Initializing database...")
        db_manager = await init_database()

        logger.info("Running database migrations...")
        applied_migrations = await run_migrations(db_manager)
        if applied_migrations:
            logger.info(f"Applied migrations: {applied_migrations}")
        else:
            logger.info("Database is up to date")

        # Initialize metric registry
        logger.info("Loading metric definitions...")
        registry = get_metric_registry()
        metric_count = len(registry.list_all())
        logger.info(f"Loaded {metric_count} metric definitions")

        # Log Phase 1 components status
        logger.info("Phase 1 Foundation components initialized", extra={
            "components": {
                "oauth": "initialized",
                "encryption": "initialized",
                "rbac": "initialized",
                "database": "connected",
                "metrics_registry": "loaded",
                "logging": "configured",
                "formatters": "ready",
            }
        })

        yield

    except Exception as e:
        logger.error(f"Failed to initialize server: {e}", exc_info=True)
        raise
    finally:
        # Cleanup
        logger.info("Shutting down Shopify Reporting MCP Server")


# Create MCP server with lifespan
mcp = FastMCP(
    name="shopify-reporting-mcp",
    version="0.1.0",
    lifespan=lifespan,
)

# Create FastAPI app for HTTP routes
app = FastAPI(
    title="Shopify Reporting MCP",
    description="Multi-store Shopify reporting and analytics MCP server",
    version="0.1.0",
)


# Request middleware for logging and context
@app.middleware("http")
async def request_middleware(request: Request, call_next):
    """Add request tracking and logging."""
    import time

    start_time = time.time()
    request_id = request.headers.get("X-Request-ID", "")

    if request_id:
        set_request_context(request_id=request_id)

    try:
        response = await call_next(request)

        duration_ms = (time.time() - start_time) * 1000

        logger.info("HTTP request completed", extra={
            "method": request.method,
            "path": request.url.path,
            "status_code": response.status_code,
            "duration_ms": round(duration_ms, 2),
        })

        return response

    except Exception as e:
        logger.error(f"Request failed: {e}", exc_info=True)
        return JSONResponse(
            status_code=500,
            content=format_error_response(e)
        )
    finally:
        clear_request_context()


# Register Shopify-specific tools
from tools.shopify import register_shopify_tools

register_shopify_tools(mcp)


# MCP Resources
@mcp.resource("config://app-settings")
def get_app_settings() -> str:
    """Return current application configuration."""
    return json.dumps({
        "name": "shopify-reporting-mcp",
        "version": "0.1.0",
        "phase": "1",
        "description": "Phase 1 Foundation - Core Infrastructure",
        "environment": os.getenv("ENVIRONMENT", "development"),
        "components": {
            "oauth": "initialized",
            "encryption": "AES-256",
            "rbac": "enabled",
            "database": "initialized",
            "metrics_registry": "loaded",
            "logging": "structured_json",
            "formatters": ["json", "markdown"],
        },
        "supported_roles": ["agency_admin", "client_viewer", "internal_admin"],
        "auth_method": "OAuth 2.0",
    }, indent=2)


@mcp.resource("status://health")
def get_health_status() -> str:
    """Return server health status."""
    return json.dumps({
        "status": "healthy",
        "phase": "1",
        "components": {
            "server": "running",
            "database": "connected",
            "shopify_oauth": "ready",
            "encryption": "ready",
            "rbac": "ready",
        },
        "timestamp": json.dumps(None),  # Will be replaced with actual timestamp
    })


@mcp.resource("metrics://definitions")
def get_metric_definitions() -> str:
    """Return all available metric definitions."""
    registry = get_metric_registry()
    metrics = [
        metric.to_dict()
        for metric in registry.list_all()
    ]
    return json.dumps({
        "metrics": metrics,
        "count": len(metrics),
        "categories": list(registry.get_category_summary().keys()),
    }, indent=2)


@mcp.resource("rbac://roles")
def get_rbac_roles() -> str:
    """Return available roles and permissions."""
    rbac = get_rbac_manager()
    return json.dumps({
        "roles": rbac.list_roles(),
    }, indent=2)


# HTTP Routes
@app.get("/health")
async def health_check():
    """Health check endpoint."""
    return {
        "status": "healthy",
        "phase": "1",
        "version": "0.1.0",
        "components": {
            "server": "running",
            "database": "connected",
            "oauth": "ready",
        },
    }


@app.get("/auth/shopify")
async def shopify_auth_init(shop: str):
    """Initialize Shopify OAuth flow."""
    try:
        oauth = get_oauth_flow()
        auth_url = oauth.get_authorization_url(shop)
        return {
            "authorization_url": auth_url,
            "shop": shop,
        }
    except Exception as e:
        error = handle_exception(e, logger)
        return JSONResponse(
            status_code=error.status_code,
            content=error.to_dict()
        )


@app.get("/auth/callback")
async def shopify_auth_callback(request: Request):
    """Handle Shopify OAuth callback."""
    try:
        params = dict(request.query_params)
        oauth = get_oauth_flow()
        result = await oauth.handle_callback(params)

        logger.info("Shopify OAuth callback successful", extra={
            "shop": result.get("shop"),
        })

        return {
            "status": "success",
            "shop": result.get("shop"),
            "scope": result.get("scope"),
        }
    except Exception as e:
        error = handle_exception(e, logger)
        return JSONResponse(
            status_code=error.status_code,
            content=error.to_dict()
        )


@app.get("/metrics")
async def list_metrics():
    """List all available metrics."""
    registry = get_metric_registry()
    return {
        "metrics": [m.to_dict() for m in registry.list_all()],
        "by_category": {
            cat.value: [m.id for m in registry.list_by_category(cat)]
            for cat in registry.list_categories()
        },
    }


@app.get("/metrics/{metric_id}")
async def get_metric(metric_id: str):
    """Get specific metric definition."""
    registry = get_metric_registry()
    metric = registry.get(metric_id)

    if not metric:
        from utils.errors import NotFoundError
        error = NotFoundError("Metric", metric_id)
        return JSONResponse(
            status_code=error.status_code,
            content=error.to_dict()
        )

    return metric.to_dict()


# Error handlers
@app.exception_handler(ShopifyMCPError)
async def mcp_error_handler(request: Request, exc: ShopifyMCPError):
    """Handle MCP-specific errors."""
    return JSONResponse(
        status_code=exc.status_code,
        content=exc.to_dict()
    )


@app.exception_handler(Exception)
async def general_error_handler(request: Request, exc: Exception):
    """Handle all other exceptions."""
    error = handle_exception(exc, logger)
    return JSONResponse(
        status_code=error.status_code,
        content=error.to_dict()
    )


if __name__ == "__main__":
    host = os.getenv("HOST", "0.0.0.0")
    port = int(os.getenv("PORT", "8000"))

    logger.info(f"Starting server on {host}:{port}")

    mcp.run(
        transport="streamable-http",
        host=host,
        port=port,
        path="/mcp"
    )
